#!/bin/bash
# ATIVE Casino Web Server Installation Script

apt update
apt install -y git curl jq file unzip make gcc g++ python3 python3-dev libnss3-dev libgconf-2-4 libxss1 libxtst6 libxrandr2 libasound2 libpangocairo-1.0-0 libcairo-gobject2 libgtk-3-0 libgdk-pixbuf2.0-dev libxcomposite1 libxdamage1 libxss1 libxtst6 libatk-bridge2.0-0 libdrm2 libxkbcommon0 libatspi2.0-0

mkdir -p /mnt/server
cd /mnt/server

if [ "${USER_UPLOAD}" == "true" ] || [ "${USER_UPLOAD}" == "1" ]; then
    echo -e "assuming user knows what they are doing have a good day."
    exit 0
fi

## get release info and download links
LATEST_JSON=$(curl --silent "https://api.github.com/repos/nodejs/node/releases/latest")
RELEASES=$(curl --silent "https://api.github.com/repos/nodejs/node/releases")

if [ -z "${VERSION}" ] || [ "${VERSION}" == "latest" ]; then
    DOWNLOAD_URL=$(echo ${LATEST_JSON} | jq .assets | jq -r '.[] | select(.name | test("linux-x64")) | .browser_download_url')
else
    VERSION_CHECK=$(echo ${RELEASES} | jq -r --arg VERSION "${VERSION}" '.[] | select(.tag_name==$VERSION) | .tag_name')
    if [ "${VERSION}" == "${VERSION_CHECK}" ]; then
        DOWNLOAD_URL=$(echo ${RELEASES} | jq -r --arg VERSION "${VERSION}" '.[] | select(.tag_name==$VERSION) | .assets[].browser_download_url' | grep -E 'linux-x64' | head -1)
    else
        echo -e "defaulting to latest release"
        DOWNLOAD_URL=$(echo ${LATEST_JSON} | jq .assets | jq -r '.[] | select(.name | test("linux-x64")) | .browser_download_url')
    fi
fi

## add some default files
echo -e "import express from 'express';
const app = express();
const port = process.env.PORT || 3000;

app.get('/', (req, res) => {
    res.json({
        status: 'online',
        message: 'ATIVE Casino Web Server',
        timestamp: new Date().toISOString()
    });
});

app.get('/health', (req, res) => {
    res.json({
        status: 'healthy',
        uptime: process.uptime(),
        memory: process.memoryUsage()
    });
});

app.listen(port, () => {
    console.log(\`🌐 ATIVE Casino Web Server running on port \${port}\`);
});" > index.js

echo -e "{
    \"name\": \"ative-casino-webserver\",
    \"version\": \"1.0.0\",
    \"description\": \"ATIVE Casino Web Server\",
    \"main\": \"index.js\",
    \"type\": \"module\",
    \"scripts\": {
        \"start\": \"node index.js\"
    },
    \"dependencies\": {
        \"express\": \"^4.18.0\"
    },
    \"engines\": {
        \"node\": \">=18.0.0\"
    }
}" > package.json

echo "Installation completed..."
echo "Default files created. Upload your project files to replace them."
echo "Run 'npm install' after uploading your files."
